namespace Janseon.Core.Battle.Sim { public static class ReinforcementRules { public static void Resolve(BattleSimState s) { if(s.Telegraphs==null)return; for(var i=0;i<s.Telegraphs.Length;i++){var t=s.Telegraphs[i];if(t.Arrived||t.ArrivalTick>s.Tick)continue; t.Arrived=true; var cell=t.Cell; for(var step=0;step<4&&Occupied(s,cell);step++)cell=cell.Step((CardinalDirection)step); } } static bool Occupied(BattleSimState s, GridCoord c) { for(var i=0;i<s.Units.Length;i++)if(s.Units[i].State!="Down"&&s.Units[i].State!="Routing"&&s.Units[i].Cell.Equals(c))return true; return false; } } }
